const tasks=[
 {id:'t1',title:'Perancangan Antarmuka Pengguna',course:'Rekayasa Interaksi',semester:'Ganjil 2026/2027',due:'2026-11-24 23:59',status:'Belum Dikumpulkan',isNew:true,desc:'Menyusun rancangan tampilan dan prototipe antarmuka berdasarkan kebutuhan pengguna.'},
 {id:'t2',title:'Implementasi Modul CRUD',course:'Pemrograman Web',semester:'Ganjil 2026/2027',due:'2026-11-27 23:59',status:'Belum Dikumpulkan',isNew:false,desc:'Menyelesaikan implementasi fungsi tambah, baca, ubah, dan hapus data.'},
 {id:'t3',title:'Analisis Dataset',course:'Analisis Data',semester:'Ganjil 2026/2027',due:'2026-11-30 21:00',status:'Belum Dikumpulkan',isNew:true,desc:'Melakukan eksplorasi dan menyusun ringkasan hasil analisis dataset.'}
];
let page='dashboard', selected='t1', chosenFile='';
const $=s=>document.querySelector(s);
function fmt(s){return new Date(s.replace(' ','T')).toLocaleString('id-ID',{day:'numeric',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit'}).replace('.',':')}
function go(p){page=p;render()}
function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600)}
function current(){return tasks.find(x=>x.id===selected)||tasks[0]}
function title(t){$('#pageCrumb').textContent=t;document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.page===page || (page==='detail'||page==='submit'||page==='success')&&n.dataset.page==='tasks'));document.querySelectorAll('.mobile-nav button').forEach(n=>n.classList.toggle('active',n.dataset.mobilePage===(page==='dashboard'?'dashboard':'tasks')))}
function taskRows(){return tasks.map(t=>`<tr data-open="${t.id}"><td><b>${t.title}</b>${t.isNew?' <span class="status new">BARU</span>':''}</td><td><span class="course">${t.course}</span><div class="muted">${t.semester}</div></td><td>${fmt(t.due)}</td><td><span class="status pending">${t.status}</span></td><td><button class="btn soft" data-detail="${t.id}">Detail</button></td></tr>`).join('')}
function render(){
 title(({dashboard:'Beranda',tasks:'Tugas Semester Ini',detail:'Detail Tugas',submit:'Pengumpulan Tugas',success:'Pengumpulan Berhasil'})[page]);
 const s=$('#screen');
 if(page==='dashboard') s.innerHTML=`<div class="heading"><div><div class="eyebrow">Ringkasan akademik</div><h1>Selamat datang, Adam</h1><p>Periksa tugas baru dan tenggat mata kuliah semester berjalan.</p></div><button class="btn primary" data-page="tasks">Lihat semua tugas →</button></div>
 <div class="stats"><div class="stat"><label>Tugas belum dikumpulkan</label><strong>3</strong><small>Semester Ganjil 2026/2027</small></div><div class="stat"><label>Tugas baru</label><strong>2</strong><small>Perlu diperiksa</small></div><div class="stat"><label>Tenggat terdekat</label><strong>24 Nov</strong><small>Rekayasa Interaksi</small></div></div>
 <div class="panel"><div class="list-head"><div><h2>Tugas yang perlu diperhatikan</h2><p class="sub">Daftar terpusat dari mata kuliah semester berjalan.</p></div><button class="btn soft" data-page="tasks">Semua tugas</button></div><div class="task-list">${tasks.slice().sort((a,b)=>a.due.localeCompare(b.due)).map(t=>`<div class="task-card"><div class="task-left"><div class="task-dot"></div><div><h3>${t.title} ${t.isNew?'<span class="status new">BARU</span>':''}</h3><div class="task-meta">${t.course} • ${t.semester}</div></div></div><div class="task-right"><div class="deadline">${fmt(t.due)}</div><button class="btn soft" data-detail="${t.id}">Lihat detail</button></div></div>`).join('')}</div></div>`;
 if(page==='tasks') s.innerHTML=`<div class="heading"><div><div class="eyebrow">Daftar terpusat</div><h1>Tugas Semester Berjalan</h1><p>Course aktif diberi penanda semester agar tidak tertukar dengan course lama.</p></div></div>
 <div class="panel table-wrap"><div class="list-head"><div><h2>Semua tugas aktif</h2><p class="sub">${tasks.length} tugas dari mata kuliah semester ini</p></div><input class="search" id="search" placeholder="Cari nama tugas atau mata kuliah…"></div><table class="table"><thead><tr><th>NAMA TUGAS</th><th>MATA KULIAH / SEMESTER</th><th>TENGGAT</th><th>STATUS</th><th>AKSI</th></tr></thead><tbody id="rows">${taskRows()}</tbody></table></div>`;
 if(page==='detail') {const t=current();s.innerHTML=`<button class="back" data-page="tasks">← Kembali ke daftar tugas</button><div class="heading"><div><div class="eyebrow">Detail tugas</div><h1>${t.title}</h1><p>Periksa informasi dan pastikan mata kuliah tujuan sudah benar.</p></div><span class="status ${t.isNew?'new':'pending'}">${t.isNew?'TUGAS BARU':t.status}</span></div><div class="detail-grid"><div class="detail-card"><div class="eyebrow">Informasi tugas</div><h2>${t.title}</h2><div class="detail-pair"><label>Mata kuliah</label><b>${t.course}</b></div><div class="detail-pair"><label>Semester</label><b>${t.semester}</b></div><div class="detail-pair"><label>Tenggat waktu</label><b>${fmt(t.due)}</b></div><div class="detail-pair"><label>Instruksi</label><span>${t.desc}</span></div><div class="detail-pair"><label>Status</label><b>${t.status}</b></div></div><div class="detail-card"><div class="eyebrow">Pemeriksaan course</div><h2>Pastikan tujuan benar</h2><p class="muted">Sebelum mengumpulkan, cocokkan nama mata kuliah dan semester dengan instruksi dosen.</p><div class="notice"><b>${t.course}</b><br>${t.semester}<br>Tujuan pengumpulan tugas</div><div class="actions"><button class="btn primary" data-page="submit">Lanjut ke pengumpulan</button></div></div></div>`}
 if(page==='submit'){const t=current();s.innerHTML=`<button class="back" data-page="detail">← Kembali ke detail tugas</button><div class="heading"><div><div class="eyebrow">Langkah pengumpulan</div><h1>Periksa Course dan Pilih Berkas</h1><p>Pastikan tugas dikirim ke mata kuliah yang sesuai.</p></div></div><div class="detail-grid"><div class="detail-card"><div class="eyebrow">Tujuan pengumpulan</div><h2>${t.course}</h2><div class="detail-pair"><label>Semester</label><b>${t.semester}</b></div><div class="detail-pair"><label>Nama tugas</label><b>${t.title}</b></div><div class="detail-pair"><label>Tenggat</label><b>${fmt(t.due)}</b></div><div class="notice">Periksa kembali identitas mata kuliah sebelum melanjutkan.</div></div><div class="detail-card"><div class="eyebrow">Berkas tugas</div><h2>Unggah berkas</h2><div class="upload-box"><b>＋ Pilih berkas dari perangkat</b><br><input id="file" type="file"><div class="muted" id="fileName">Belum ada berkas dipilih</div></div><label class="checkrow"><input id="confirm" type="checkbox"><span>Saya sudah memeriksa mata kuliah dan semester tujuan pengumpulan.</span></label><button class="btn primary" id="submitBtn" disabled>Kirim tugas (simulasi)</button><div class="muted" style="font-size:10px;margin-top:10px">Prototype ini tidak mengirim berkas ke server LMS.</div></div></div>`}
 if(page==='success'){const t=current();s.innerHTML=`<div class="confirm-card"><div class="success-icon">✓</div><div class="eyebrow">Simulasi selesai</div><h1>Pengumpulan Berhasil</h1><p>Alur prototype berhasil diselesaikan. Status di bawah hanya simulasi, bukan catatan resmi LMS.</p><div class="confirm-info"><div class="detail-pair"><label>Nama tugas</label><b>${t.title}</b></div><div class="detail-pair"><label>Mata kuliah</label><b>${t.course}</b></div><div class="detail-pair"><label>Semester</label><b>${t.semester}</b></div><div class="detail-pair"><label>Status simulasi</label><b>Sudah Dikumpulkan</b></div></div><button class="btn primary" data-page="tasks">Kembali ke daftar tugas</button></div>`}
 s.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.page)));
 s.querySelectorAll('[data-detail]').forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.detail;go('detail')}));
 s.querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',e=>{if(!e.target.closest('button')){selected=b.dataset.open;go('detail')}}));
 if($('#search')) $('#search').addEventListener('input',e=>{$('#rows').innerHTML=taskRows();const q=e.target.value.toLowerCase();$('#rows').querySelectorAll('tr').forEach(r=>r.hidden=!r.innerText.toLowerCase().includes(q));$('#rows').querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{selected=b.dataset.detail;go('detail')})});
 if($('#file')) $('#file').addEventListener('change',e=>{$('#fileName').textContent=e.target.files[0]?.name||'Belum ada berkas dipilih';checkSubmit()});
 if($('#confirm')) $('#confirm').addEventListener('change',checkSubmit);
 if($('#submitBtn')) $('#submitBtn').addEventListener('click',()=>go('success'));
}
function checkSubmit(){ $('#submitBtn').disabled=!($('#file')?.files?.length && $('#confirm')?.checked); }
document.querySelectorAll('.nav').forEach(n=>n.addEventListener('click',()=>go(n.dataset.page)));
document.querySelectorAll('.mobile-nav button').forEach(n=>n.addEventListener('click',()=>go(n.dataset.mobilePage)));
render();
